export async function listTools() {
  return [
    {
      name: 'calculate',
      description: 'Perform a basic arithmetic operation on two numbers.',
      inputSchema: {
        type: 'object',
        properties: {
          a: { type: 'number' },
          b: { type: 'number' },
          operation: { type: 'string', enum: ['add', 'subtract', 'multiply', 'divide'] }
        },
        required: ['a', 'b', 'operation'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'calculate') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const { a, b, operation } = args;

  // Validate no extra fields
  const allowed = new Set(['a', 'b', 'operation']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown field: ${key}`);
    }
  }

  // Validate presence
  if (a === undefined || b === undefined || operation === undefined) {
    throw new Error('Missing required field(s): a, b, operation');
  }

  // Validate numeric
  if (typeof a !== 'number' || !Number.isFinite(a)) {
    throw new Error('Field "a" must be a finite number');
  }
  if (typeof b !== 'number' || !Number.isFinite(b)) {
    throw new Error('Field "b" must be a finite number');
  }

  // Validate operation
  const ops = ['add', 'subtract', 'multiply', 'divide'];
  if (!ops.includes(operation)) {
    throw new Error(`Unsupported operation: ${operation}`);
  }

  let result;
  switch (operation) {
    case 'add': result = a + b; break;
    case 'subtract': result = a - b; break;
    case 'multiply': result = a * b; break;
    case 'divide':
      if (b === 0) throw new Error('Division by zero');
      result = a / b; break;
  }

  return { content: [{ type: 'text', text: String(result) }] };
}
